mapper.select:
SELECT * FROM ( SELECT d.contentid, d.contenttypeid, d.title, d.addr1, d.addr2, d.tel, d.firstimage, d.firstimage2, d.mapx, d.mapy, ct.type_name, r.regn_name, s.signgu_name, /* Haversine 공식으로 거리 계산 (km) */ ROUND( 6371 * ACOS( LEAST(1, GREATEST(-1, COS(#{lat} * 3.141592653589793 / 180) * COS(d.mapy * 3.141592653589793 / 180) * COS((d.mapx - #{lng}) * 3.141592653589793 / 180) + SIN(#{lat} * 3.141592653589793 / 180) * SIN(d.mapy * 3.141592653589793 / 180) )) ), 2 ) AS distance FROM destination d LEFT JOIN content_type ct ON d.contenttypeid = ct.contenttypeid LEFT JOIN ldong_regn_code r ON d.lDongRegnCd = r.lDongRegnCd LEFT JOIN ldong_signgu_code s ON d.lDongRegnCd = s.lDongRegnCd AND d.lDongSignguCd = s.lDongSignguCd WHERE d.mapx IS NOT NULL AND d.mapy IS NOT NULL AND d.contenttypeid NOT IN ('15', '25') /* ★ 이벤트 제외 */ /* 관광 타입 필터 (선택) */
AND d.contenttypeid = #{contenttypeid}
ORDER BY distance ASC ) WHERE distance <= #{radius} AND ROWNUM <= #{limit}

SELECT * FROM ( SELECT d.contentid, d.contenttypeid, d.title, d.addr1, d.addr2, d.tel, d.firstimage, d.firstimage2, d.mapx, d.mapy, NULL AS distance, ct.type_name, r.regn_name, s.signgu_name FROM destination d LEFT JOIN content_type ct ON d.contenttypeid = ct.contenttypeid LEFT JOIN ldong_regn_code r ON d.lDongRegnCd = r.lDongRegnCd LEFT JOIN ldong_signgu_code s ON d.lDongRegnCd = s.lDongRegnCd AND d.lDongSignguCd = s.lDongSignguCd WHERE d.mapx IS NOT NULL AND d.mapy IS NOT NULL AND d.lDongRegnCd = #{lDongRegnCd} AND d.contenttypeid NOT IN ('15', '25') /* ★ 이벤트 제외 */ /* 시군구 필터 (선택) */
AND d.lDongSignguCd = #{lDongSignguCd}
/* 관광 타입 필터 (선택) */
AND d.contenttypeid = #{contenttypeid}
ORDER BY d.view_count DESC NULLS LAST, d.title ASC ) WHERE ROWNUM <= #{limit}

SELECT * FROM ( SELECT d.contentid, d.contenttypeid, d.title, d.addr1, d.addr2, d.tel, d.firstimage, d.firstimage2, d.mapx, d.mapy, NULL AS distance, ct.type_name, r.regn_name, s.signgu_name FROM destination d LEFT JOIN content_type ct ON d.contenttypeid = ct.contenttypeid LEFT JOIN ldong_regn_code r ON d.lDongRegnCd = r.lDongRegnCd LEFT JOIN ldong_signgu_code s ON d.lDongRegnCd = s.lDongRegnCd AND d.lDongSignguCd = s.lDongSignguCd WHERE d.mapx IS NOT NULL AND d.mapy IS NOT NULL AND d.contenttypeid NOT IN ('15', '25') /* ★ 이벤트 제외 */ AND ( UPPER(d.title) LIKE '%' || UPPER(#{keyword}) || '%' OR UPPER(d.addr1) LIKE '%' || UPPER(#{keyword}) || '%' ) /* 관광 타입 필터 (선택) */
AND d.contenttypeid = #{contenttypeid}
ORDER BY /* 제목에 키워드가 포함된 경우 우선 정렬 */ CASE WHEN UPPER(d.title) LIKE '%' || UPPER(#{keyword}) || '%' THEN 0 ELSE 1 END, d.view_count DESC NULLS LAST, d.title ASC ) WHERE ROWNUM <= #{limit}
